window.initWaterSupplyLayer = function(map) {
    var layerGroup = L.layerGroup();
    
    if (!window.AP_WATER_SUPPLY_GEOJSON || !window.AP_WATER_SUPPLY_GEOJSON.features) {
        return layerGroup;
    }
    
    L.geoJSON(window.AP_WATER_SUPPLY_GEOJSON, {
        style: function(feature) {
            var isCanal = (feature.properties.type === 'Gravity Flow Water Canal');
            return {
                color: isCanal ? '#0284c7' : '#06b6d4',
                weight: isCanal ? 3.5 : 2.5,
                opacity: 0.9,
                dashArray: isCanal ? '5 5' : null
            };
        },
        pointToLayer: function(feature, latlng) {
            return L.circleMarker(latlng, {
                radius: 6,
                fillColor: '#0284c7',
                color: '#ffffff',
                weight: 2,
                opacity: 1,
                fillOpacity: 0.95
            });
        },
        onEachFeature: function(feature, layer) {
            var p = feature.properties;
            if (feature.geometry.type === 'Point') {
                layer.bindTooltip(`
                    <div style="font-family: Inter, sans-serif; min-width: 170px;">
                        <div style="font-weight: 800; color: #0284c7; font-size: 12px;"><i class="fas fa-water"></i> ${p.name}</div>
                        <div style="font-size: 10.5px; color: #0f172a; margin-top: 2px;"><strong>Capacity:</strong> ${p.capacity}</div>
                        <div style="font-size: 10px; color: #64748b;"><strong>Operator:</strong> ${p.operator}</div>
                    </div>
                `, { direction: 'top', offset: [0, -6] });
            } else {
                layer.bindTooltip(`
                    <div style="font-family: Inter, sans-serif; min-width: 180px;">
                        <div style="font-weight: 800; color: #0284c7; font-size: 12px;"><i class="fas fa-faucet"></i> ${p.name}</div>
                        <div style="font-size: 10.5px; color: #0f172a; margin-top: 2px;"><strong>Type:</strong> ${p.type} (${p.diameter})</div>
                        <div style="font-size: 10px; color: #475569;"><strong>Capacity:</strong> ${p.capacity_mld}</div>
                        <div style="font-size: 9.5px; color: #64748b;"><strong>Authority:</strong> ${p.operator}</div>
                    </div>
                `, { direction: 'top', offset: [0, -6] });
            }
        }
    }).addTo(layerGroup);
    
    return layerGroup;
};
